import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'5LA4CuIHLWigh48x3qaW',titulo:'Chuveiro elétrico de parede Lorenzetti Futura Multitemperaturas branco 6800W'},{id:'5Nr0nOkBvYhG9KXxeyZL',titulo:'Kit Wella Brilliance Sh 250ml + Cond 200ml + Másc 150ml'},{id:'6C1vEnfqaRRxkR4DIGa6',titulo:'Extensao Eletrica 30 Metros Reforcada 3 Tomadas Cabo Resistente 10a 20a Bivolt Uso Profissional Residencial Obra Alta Durabilidade',listing:'MLB4646190273'}];
test('triagem54 exige identidade e preserva operação, variantes e afiliados com idempotência',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},...(r.listing?[{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}]:[])])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Futura não fornece dimensionamento ou presume bivolt e instalação universal',()=>{const x=correctProductData(rows[0]);assert.equal(x.titulo,rows[0].titulo);assert.match(x.comentario,/associa 6800 W a 220 V/);assert.match(x.comentario,/não dimensiona circuito, condutores ou proteção/);assert.doesNotMatch(x.pros,/bivolt|\d+\s*mm|disjuntor|boiler|solar|economia/i);});
test('Wella mantém volumes e evita resultado cosmético garantido',()=>{const x=correctProductData(rows[1]);assert.equal(x.titulo,rows[1].titulo);assert.match(x.comentario,/não foram verificadas pela equipe/);assert.match(x.comentario,/Não transferimos composição/);assert.doesNotMatch(x.pros,/sela|repõe|garant|desbotamento|nutriente|semanas/i);});
test('extensão não confirma capacidade ou carga por encaixe',()=>{const x=correctProductData(rows[2]);assert.match(x.titulo,/capacidade a confirmar/);assert.match(x.comentario,/não recomendamos|não permitem a esta ficha assegurar/);assert.match(x.comentario,/Não use os números.*como dimensionamento/);assert.doesNotMatch(x.pros,/\b20\s*A|\b10\s*A|750|1300|profissional|reforçad|certificad/i);assert.doesNotMatch(x.titulo,/bivolt|10a|20a|profissional|durabilidade/i);});
